// 1. DETECTA · Valida el origen y el formato antes de tocar la BD o GLPI.
// El webhook no tiene usuario: sin el secreto compartido cualquiera en la red podría enviar
// un hash falso (o el de la línea base, que cerraría el incidente). Lo que no trae el token se descarta.
const it = $input.first().json;
const h = it.headers || {};
const body = it.body || {};
const esperado = String($env.HASH_WEBHOOK_TOKEN || '');
if (!esperado || esperado === '__cambiar__' || String(h['x-hash-token'] || '') !== esperado) return [];

const hash = String(body.hash_sshd || '').trim().toLowerCase();
const host = String(body.host || '').trim();
if (!/^[a-f0-9]{64}$/.test(hash) || !/^[A-Za-z0-9._-]{1,64}$/.test(host)) return [];
const timestamp = String(body.timestamp || '').replace(/[^0-9TZ:.\-]/g, '').slice(0, 30) || new Date().toISOString();

// host y hash ya están validados con listas blancas: se pueden interpolar en el SQL sin riesgo de inyección
const sql_estado =
  `SELECT h.host, b.hash AS base, i.ticket_id AS abierto ` +
  `FROM (VALUES ('${host}')) AS h(host) ` +
  `LEFT JOIN sshd_baseline b ON b.host = h.host ` +
  `LEFT JOIN LATERAL (SELECT ticket_id FROM glpi_incidentes WHERE host = h.host AND cerrado IS NULL ` +
  `ORDER BY creado DESC LIMIT 1) i ON true;`;
return [{ json: { hash, host, timestamp, sql_estado } }];

// 2. DECIDE y 3. GESTIONA · Compara con la línea base, consulta GLPI y crea o cierra el incidente.
// Salida: { alertas: [...para Enviar_Alerta], sql: [...estado en PostgreSQL], aviso: 'texto informativo' }
const d = $('Validar origen y hash').first().json;
const e = $input.first().json;
const base = e.base ? String(e.base).trim() : null;
const abierto = e.abierto ? Number(e.abierto) : null;
const out = { alertas: [], sql: [], aviso: '' };
const corto = x => x ? x.slice(0, 8) + '…' + x.slice(-4) : '—';
const ahora = $now.setZone('America/Costa_Rica').toFormat('yyyy-MM-dd HH:mm:ss');
const alerta = (codigo, severidad, tipo, valor, accion, ticket) => ({
  codigo, severidad, tipo,
  tabla: `sshd_config · ${d.host}`,
  detalle: `Valor detectado: ${valor}\nTicket GLPI: ${ticket ? '#' + ticket : 'sin ticket'}`,
  query: 'sha256sum /etc/ssh/sshd_config',
  usuario: 'scripts/hash_sshd.sh',
  accion
});

// a) Primer envío de este servidor: se registra la línea base (paso 1 del estudio de caso)
if (!base) {
  out.sql.push(`INSERT INTO sshd_baseline (host, hash, motivo) VALUES ('${d.host}', '${d.hash}', ` +
               `'Línea base inicial (primer envío del script)') ON CONFLICT (host) DO NOTHING;`);
  out.aviso = `ℹ️ Línea base registrada · NutriAnimales S.A. | Proyecto II\nFecha: ${ahora}\nHost: ${d.host}\n` +
              `Hash SHA-256 de sshd_config: ${d.hash}\nControl: ISO/IEC 27001 A.8.9`;
  return [{ json: out }];
}
// b) Sin novedad: hash igual a la línea base y ningún incidente abierto
if (d.hash === base && !abierto) return [{ json: out }];
// c) El cambio ya tiene incidente abierto: no se repiten C1/C2 en cada ejecución del cron
if (d.hash !== base && abierto) return [{ json: out }];

// ---- API REST de GLPI (red interna; tokens en el .env) ----
const API = $env.GLPI_API_URL;
const cab = { 'Content-Type': 'application/json', 'App-Token': $env.GLPI_APP_TOKEN };
const req = (method, path, body, extra = {}) =>
  this.helpers.httpRequest({ method, url: API + path, headers: { ...cab, ...extra }, body, json: true });
const abrirSesion = async () => {
  const s = await req('GET', '/initSession', undefined, { Authorization: 'user_token ' + $env.GLPI_USER_TOKEN });
  cab['Session-Token'] = s.session_token;
};
const cerrarSesion = () => req('GET', '/killSession').catch(() => {});

await abrirSesion();
try {
  if (d.hash === base) {
    // d) El hash volvió a la línea base → cierre automático del incidente (paso 5 del estudio de caso)
    const t = await req('GET', `/Ticket/${abierto}`).catch(() => null);
    if (t && Number(t.status) < 5) {
      await req('POST', '/ITILFollowup', { input: { itemtype: 'Ticket', items_id: abierto,
        content: `Cierre automático por N8N (${ahora}): el hash de sshd_config volvió a la línea base (${corto(d.hash)}).` } });
      await req('PUT', `/Ticket/${abierto}`, { input: { status: 6 } });   // 6 = Cerrado
    }
    out.sql.push(`UPDATE glpi_incidentes SET cerrado = NOW(), cierre = 'Automático: el hash volvió a la línea base' ` +
                 `WHERE ticket_id = ${abierto} AND cerrado IS NULL;`);
    out.aviso = `✅ Incidente #${abierto} cerrado automáticamente · NutriAnimales S.A. | Proyecto II\nFecha: ${ahora}\n` +
                `Host: ${d.host}\nValor detectado: hash ${corto(d.hash)} = línea base\n` +
                `Acción: registrar el Problem con la causa raíz en GLPI y vincularlo al incidente #${abierto}.`;
    return [{ json: out }];
  }

  // e) Hash distinto y sin incidente abierto: ¿hay un Change aprobado y no aplicado para el servidor?
  const equipos = await req('GET', '/Computer?range=0-999');
  const srv = (Array.isArray(equipos) ? equipos : []).find(c => c.name === d.host);
  let aprobado = null;
  if (srv) {
    const links = await req('GET', `/Computer/${srv.id}/Change_Item`).catch(() => []);
    for (const l of (Array.isArray(links) ? links : [])) {
      const ch = await req('GET', `/Change/${l.changes_id}`).catch(() => null);
      // global_validation 3 = aprobado · se excluyen aplicado (5), cerrado (6), cancelado (13) y rechazado (14)
      if (ch && Number(ch.global_validation) === 3 && ![5, 6, 13, 14].includes(Number(ch.status))) { aprobado = ch; break; }
    }
  }
  const valor = `hash ${corto(d.hash)} ≠ línea base ${corto(base)}`;

  if (aprobado) {
    // Cambio autorizado (A.8.32): solo C1 informativa y el hash nuevo pasa a ser la línea base
    await req('POST', '/ITILFollowup', { input: { itemtype: 'Change', items_id: aprobado.id,
      content: `N8N (${ahora}): sshd_config cambió en ${d.host}. Nuevo hash de línea base: ${d.hash}.` } }).catch(() => {});
    out.sql.push(`UPDATE sshd_baseline SET hash = '${d.hash}', actualizado = NOW(), motivo = 'Change #${Number(aprobado.id)} aprobado' ` +
                 `WHERE host = '${d.host}';`);
    out.alertas.push(alerta('C1', 'ADVERTENCIA', 'Cambio en configuración crítica (cubierto por un Change aprobado)', valor,
      `Cambio cubierto por el Change #${aprobado.id}. El hash nuevo queda como línea base.`, null));
    return [{ json: out }];
  }

  // Cambio NO autorizado → incidente crítico con SLA de 1 hora (A.5.26) + C1 y C2
  const cat = Number($env.GLPI_CATEGORIA_ID || 0);
  const sla = Number($env.GLPI_SLA_CRITICO_ID || 0);
  const input = {
    name: `Cambio no autorizado en sshd_config · ${d.host}`,
    content: [
      'Incidente creado automáticamente por N8N (alertas C1 y C2).',
      `Host: ${d.host}`,
      `Fecha de detección: ${ahora} (script: ${d.timestamp})`,
      `Hash detectado: ${d.hash}`,
      `Hash de línea base: ${base}`,
      'Change aprobado en GLPI: No',
      'Severidad: Crítica · SLA de resolución: 1 hora',
      'Acción sugerida: identificar quién modificó sshd_config, registrar y aprobar un Change o revertir el archivo a la línea base.',
      'Controles: ISO/IEC 27001 A.8.9, A.8.32 y A.5.26.'
    ].join('<br>'),
    type: 1,                 // incidente
    urgency: 5, impact: 5, priority: 6   // prioridad "Mayor"
  };
  if (cat) input.itilcategories_id = cat;   // la regla de negocio de la categoría también puede asignar el SLA
  if (sla) input.slas_id_ttr = sla;         // SLA crítico de 1 hora asignado directamente
  if (srv) input.items_id = { Computer: [srv.id] };   // vínculo con el activo de la CMDB (A.5.9)
  const t = await req('POST', '/Ticket', { input });
  const id = Number(t.id);
  out.sql.push(`INSERT INTO glpi_incidentes (ticket_id, host, hash_detectado, hash_base) ` +
               `VALUES (${id}, '${d.host}', '${d.hash}', '${base}') ON CONFLICT (ticket_id) DO NOTHING;`);
  out.alertas.push(alerta('C1', 'CRÍTICA', 'Cambio en configuración crítica', valor,
    'Verificar quién modificó sshd_config y comparar el archivo contra la línea base (ISO/IEC 27001 A.8.9).', id));
  out.alertas.push(alerta('C2', 'CRÍTICA', 'Cambio sin ticket aprobado',
    `no existe un Change aprobado en GLPI para ${d.host}`,
    'Registrar y aprobar un Change en GLPI o revertir sshd_config a la línea base. SLA de resolución: 1 hora (A.8.32).', id));
} finally {
  await cerrarSesion();
}
return [{ json: out }];

// Avisos informativos (línea base registrada, cierre automático): no son alertas C1–C3
const a = $input.first().json.aviso;
return a ? [{ json: { texto: a } }] : [];
